mapper.select:
select t.cpi_id,t.cpi_id cpiId,t.machine_id,t.machine_id machineId,t.create_time,t.create_time
createTime,t.frame_type,t.frame_type frameType,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id
communityId,t.type,t.content,t.order_id,t.order_id orderId
from charge_process_info t
where 1 =1

    and t.cpi_id= #{cpiId}


    and t.machine_id= #{machineId}


    and t.create_time= #{createTime}


    and t.frame_type= #{frameType}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.order_id= #{orderId}


    and t.type= #{type}


    and t.content= #{content}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
