    , t.order_id= #{orderId}


    , t.cpi_id= #{cpiId}


    , t.machine_id= #{machineId}


    , t.create_time= #{createTime}


    , t.frame_type= #{frameType}


    , t.community_id= #{communityId}


    , t.type= #{type}


    , t.content= #{content}

where 1=1

